'use strict';

const { setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

const TODOAPP_HTML = `
<section class="todoapp">
  <header class="header">
    <h1>todos</h1>
    <input class="new-todo" placeholder="What needs to be done?" autofocus>
  </header>
  <section class="main">
    <input id="toggle-all" class="toggle-all" type="checkbox">
    <label for="toggle-all">Mark all as complete</label>
    <ul class="todo-list"></ul>
  </section>
  <footer class="footer">
    <span class="todo-count"><strong>0</strong> items left</span>
    <ul class="filters">
      <li><a href="#/">All</a></li>
      <li><a href="#/active">Active</a></li>
      <li><a href="#/completed">Completed</a></li>
    </ul>
    <button class="clear-completed">Clear completed</button>
  </footer>
</section>
`;

class TodoWorld {
  constructor({ attach, parameters }) {
    this.attach = attach;
    this.parameters = parameters;
    this.window = null;
    this.document = null;
    this.savedTodos = null;
  }

  setupPage() {
    this.window = new Window({ url: 'http://localhost:8080/' });
    this.document = this.window.document;
    this.document.body.innerHTML = TODOAPP_HTML;

    // Restore saved todos if doing a reload
    if (this.savedTodos !== null) {
      this.window.localStorage.setItem('todos-todomvc', this.savedTodos);
    }

    // Load and execute the app
    const appCode = fs.readFileSync(path.join(__dirname, '..', '..', 'js', 'app.js'), 'utf-8');
    this.window.eval(appCode);
  }

  reloadPage() {
    // Save localStorage state before reload
    this.savedTodos = this.window.localStorage.getItem('todos-todomvc');
    // Reload (fresh window, same localStorage data)
    this.setupPage();
    // Clear saved state - it has been used
    this.savedTodos = null;
  }

  getTodos() {
    return this.window._todoApp.getTodos();
  }

  addTodoToData(title, completed) {
    const todos = this.getTodos();
    todos.push({ id: Date.now() + Math.random(), title, completed });
    this.window._todoApp.setTodos(todos);
    this.window._todoApp.saveTodos();
    this.window._todoApp.render();
  }

  findTodoLiByTitle(title) {
    const items = this.document.querySelectorAll('.todo-list li');
    for (let i = 0; i < items.length; i++) {
      const label = items[i].querySelector('.view label');
      if (label && label.textContent === title) return items[i];
    }
    return null;
  }

  dispatchClick(element) {
    element.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }

  dispatchDblClick(element) {
    element.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  }

  dispatchKeyDown(element, keyCode) {
    element.dispatchEvent(new this.window.KeyboardEvent('keydown', { keyCode, bubbles: true }));
  }

  dispatchBlur(element) {
    element.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
  }

  cleanup() {
    if (this.window && this.window.close) {
      this.window.close();
    }
    this.window = null;
    this.document = null;
    this.savedTodos = null;
  }
}

setWorldConstructor(TodoWorld);

'use strict';

const { Given, When, Then, Before, After } = require('@cucumber/cucumber');
const assert = require('assert');

// --- Hooks ---

Before(function () {
  // World starts with no window
});

After(function () {
  this.cleanup();
});

// --- Helper: add todo with programmatic data and render ---

function addTodo(world, title, completed) {
  const todos = world.getTodos();
  const maxId = todos.reduce(function (m, t) { return Math.max(m, t.id); }, 0);
  todos.push({ id: maxId + 1, title: title, completed: completed });
  world.window._todoApp.setTodos(todos);
  world.window._todoApp.saveTodos();
  world.window._todoApp.render();
}

// --- Given steps ---

Given('the page is loaded with no todos', function () {
  this.setupPage();
});

Given('the page is loaded with one active todo and no completed todos', function () {
  this.setupPage();
  addTodo(this, 'Task one', false);
});

Given('the page is loaded with two active todos', function () {
  this.setupPage();
  addTodo(this, 'Task one', false);
  addTodo(this, 'Task two', false);
});

Given('the page is loaded with two active todos and one completed todo', function () {
  this.setupPage();
  addTodo(this, 'Task one', false);
  addTodo(this, 'Task two', false);
